// bleibt (z.B. LLM-Call kam ohne n8n-Fehler, aber mit leerem Text zurueck,
// UND intentData.reply ist fuer diesen Intent bewusst auf null erzwungen --
// aktuell der Fall bei query_lead), landet hier sonst der JS-Wert null bzw.
// undefined. escapeHtml() ruft intern String(text) auf -- String(null) ist
// woertlich die Zeichenkette "null" und wuerde unveraendert an den Nutzer
// gesendet (siehe Incident 20.09., "zeig mir den lead jo marketing" -> "null").
if (reply === null || reply === undefined || reply === '') {
  reply = 'Sorry, da ist gerade etwas schiefgelaufen. Versuch es gleich nochmal.';
