function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/_/g, ' ')
    .replace(/\*/g, ' ')
    .replace(/`/g, "'");
}

// NEU (22.09.): zentrales Copy-Paste-Wrapping fuer alle Intents -- identische Logik wie in
// "Vision-Antwort formatieren", von dort uebernommen. Wickelt jeden "Nachrichtenvorschlag:"-
// Abschnitt in <pre> (Telegram HTML) fuer Ein-Tap-Copy-Paste. Laeuft auf dem bereits
// HTML-escapten Text, damit die eingefuegten <pre>/</pre>-Tags das einzige echte Markup sind.
// No-op fuer jeden Intent, dessen Reply kein "Nachrichtenvorschlag:"-Label enthaelt.
function wrapMessageSuggestion(text) {
  return text.replace(
    /(\bNachrichtenvorschlag:[ \t]*\n?)([\s\S]*?)(?=\n\s*-{3,}\s*\n|\n\s*Optionaler LinkedIn-Kommentar:|\n\s*(?:#{1,3}\s*)?Kontakt:\s|$)/gi,
    (full, header, message) => {
      const trimmed = message.trim();
      if (!trimmed) return full;
      return `${header}\n<pre><code class="language-plain">${trimmed}</code></pre>`;
    }
  );
}

return [{
  json: {
