// Kette lautlos nie laufen zu lassen (gleiche Fehlerklasse wie der
// Termin-Radar-Teil-B-Bug). Ohne echte Zeile fehlt row.id -- klare eigene
// Fehlermeldung statt der irrefuehrenden "nicht in Kandidatenliste
// gefunden"-Meldung weiter unten, die eine falsche Auswahl suggerieren wuerde.
if (!row || !row.id) {
  throw new Error("Diese Auswahl ist nicht mehr gueltig (abgelaufen oder bereits verarbeitet) -- bitte den Befehl nochmal schicken.");
}

// NEU: HubSpot-Notiz-Auswahl behandeln, komplett getrennt vom Kalender-Pfad
if (row.action === 'add_note') {
  const candidates = row.candidates || [];
  const match = candidates.find(c => c.hs_id === intentData.selected_hubspot_id);
  if (!match) {
    throw new Error("Ausgewaehlter HubSpot-Eintrag nicht in Kandidatenliste gefunden");
  }
  return [{
    json: {
      isHubspotNote: true,
      hs_id: match.hs_id,
      hs_type: match.hs_type,
      note_text: row.note_text,
      disambiguationId: row.id
    }
  }];
}

// NEU: Deal-Stage-Auswahl behandeln, komplett getrennt vom Kalender-Pfad und vom Note-Pfad
if (row.action === 'update_stage') {
  const candidates = row.candidates || [];
  const match = candidates.find(c => c.hs_id === intentData.selected_hubspot_id);
  if (!match) {
    throw new Error("Ausgewaehlter Deal nicht in Kandidatenliste gefunden");
  }
  return [{
    json: {
      isHubspotNote: false,
      isUpdateStage: true,
      hs_id: match.hs_id,
      dealName: match.title,
      newStageRaw: row.deal_stage_raw,
      disambiguationId: row.id
    }
  }];
}

const candidates = row.candidates || [];
const match = candidates.find(c => c.id === intentData.selected_event_id);
if (!match) {
  throw new Error("Ausgewaehlter Termin nicht in Kandidatenliste gefunden");
}
const rawNewStart = (row.new_start_raw && row.new_start_raw !== 'null')
  ? row.new_start_raw
  : (intentData.new_start || null);
const hasNewStart = !!rawNewStart;
// Move ohne neue Zeit: kann noch nicht final ausgefuehrt werden
if (row.action === 'move' && !hasNewStart) {
  return [{
    json: {
      isHubspotNote: false,
      needsTime: true,
      eventId: match.id,
      eventTitle: match.title,
      disambiguationId: row.id,
      matchJson: JSON.stringify(match),
      reply: `Auf welche Uhrzeit soll ich "${match.title}" verschieben?`
    }
  }];
}
function berlinStringToUTCDate(dateStr) {
  const [datePart, timePart] = dateStr.split(' ');
  const [y, m, d] = datePart.split('-').map(Number);
  const [hh, mm] = timePart.split(':').map(Number);
  const guess = new Date(Date.UTC(y, m - 1, d, hh, mm));
  const utcStr = guess.toLocaleString('en-US', { timeZone: 'UTC' });
  const berlinStr = guess.toLocaleString('en-US', { timeZone: 'Europe/Berlin' });
  const offsetMs = new Date(berlinStr) - new Date(utcStr);
  return new Date(guess.getTime() - offsetMs);
}
let newEnd = null;
let newStartUTC = null;
if (row.action === 'move' && hasNewStart) {
  const origStart = new Date(match.start);
  const origEnd = new Date(match.end);
  const durationMs = origEnd - origStart;
  newStartUTC = berlinStringToUTCDate(rawNewStart);
  newEnd = new Date(newStartUTC.getTime() + durationMs).toISOString();
}
return [{
  json: {
    isHubspotNote: false,
    needsTime: false,
    action: row.action,
    eventId: match.id,
    eventTitle: match.title,
    newStart: newStartUTC ? newStartUTC.toISOString() : null,
    newEnd: newEnd,
    disambiguationId: row.id
  }
}];

const count = $json.matchCount;
return [{
  json: {
    reply: `Ich hab ${count} Mails mit diesem Suchbegriff gefunden — das sind ziemlich viele. Kannst du genauer sagen wonach du suchst (z.B. Absendername oder Zeitraum)?`
  }
}];

const mails = $input.first().json.value || [];

function findSenderAddress(m) {
  const candidates = [
    m?.from?.emailAddress?.address,
    m?.sender?.emailAddress?.address,
    m?.from,
    m?.sender,
  ];
  for (const c of candidates) {
    if (typeof c === 'string' && c.includes('@')) return c.trim();
  }
  return '';
}
function findSenderName(m) {
  const candidates = [
    m?.from?.emailAddress?.name,
    m?.sender?.emailAddress?.name,
  ];
  for (const c of candidates) {
    if (typeof c === 'string' && c.trim()) return c.trim();
  }
  return '';
}

const compact = mails.map(m => ({
  subject: m.subject || '(kein Betreff)',
  sender: findSenderName(m) || findSenderAddress(m) || 'Unbekannt',
  receivedAt: m.receivedDateTime,
  isRead: m.isRead,
  preview: (m.bodyPreview || '').slice(0, 200)
}));

return [{
  json: {
    matchCount: compact.length,
    matches: compact
  }
}];

function safeAll(nodeName) {
  try {
    return $(nodeName).all().map(item => item.json);
  } catch (e) {
    return [];
  }
}
const deals = safeAll('HubSpot Deals suchen').filter(item => item.id);
const contacts = safeAll('HubSpot Kontakte suchen').filter(item => item.id);
const compactDeals = deals.map(d => ({
  type: 'deal',
  id: d.id,
  name: d.properties?.dealname || '(kein Name)',
  stage: d.properties?.dealstage || '',
  amount: d.properties?.amount || null
}));
const compactContacts = contacts.map(c => ({
  type: 'contact',
  id: c.id,
  name: `${c.properties?.firstname || ''} ${c.properties?.lastname || ''}`.trim() || '(kein Name)',
  email: c.properties?.email || '',
  company: c.properties?.company || ''
}));
return [{
  json: {
    matchCount: compactDeals.length + compactContacts.length,
    deals: compactDeals,
    contacts: compactContacts
  }
}];

