function toBerlinString(isoString) {
  if (!isoString) return null;
  // Outlook liefert UTC ohne 'Z' Suffix oft als naive ISO-String - explizit als UTC parsen
  const utcDate = new Date(isoString.endsWith('Z') ? isoString : isoString + 'Z');
  const berlin = utcDate.toLocaleString('de-DE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit'
  });
  return berlin; // Format: TT.MM.JJJJ, HH:MM
}

// NEU (25.09.2026, praeventiver Audit-Fix "Ebene 1"): Wochentag wird HIER deterministisch
// berechnet und als eigenes Feld + fertiges displayLabel mitgegeben, statt die formulierende
// LLM Call (LLM Call 3) das Datum selbst in Wochentage uebersetzen zu lassen. Gleiche
// Bug-Klasse wie beim Wochentag-Fix bei create_event/save_memory (LLM erfindet/verrechnet
// sich beim Wochentag) -- hier praeventiv gefixt, bevor ein Incident gemeldet wurde.
const weekdayNames = ['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'];

function weekdayFromIso(isoString) {
  if (!isoString) return null;
  const utcDate = new Date(isoString.endsWith('Z') ? isoString : isoString + 'Z');
  const berlinDateStr = utcDate.toLocaleString('en-US', { timeZone: 'Europe/Berlin' });
  const berlinDate = new Date(berlinDateStr);
  return weekdayNames[berlinDate.getDay()];
}

const events = $input.first().json.value || [];
