  const endBerlin = toBerlinString(e.end?.dateTime);
  const weekday = weekdayFromIso(e.start?.dateTime);
  const isAllDay = e.isAllDay || false;

  let displayLabel;
  if (!startBerlin) {
    displayLabel = e.subject || '(kein Titel)';
  } else if (isAllDay) {
    displayLabel = `${weekday}, ${startBerlin.split(',')[0]} (ganztaegig)`;
  } else {
    const startTime = startBerlin.split(', ')[1] || '';
    const endTime = endBerlin ? (endBerlin.split(', ')[1] || '') : '';
    displayLabel = `${weekday}, ${startBerlin.split(',')[0]}, ${startTime}${endTime ? '–' + endTime : ''} Uhr`;
  }

  return {
    title: e.subject || '(kein Titel)',
    start: startBerlin,
    end: endBerlin,
    weekday,
    displayLabel,
    location: e.location?.displayName || null,
    isAllDay,
