parameters.jsCode:
const raw = $json.text || '';
let cleanText = raw;
let leads = [];

// Mistral does not always hit the exact "LEADS_JSON:" format -- seen in production writing
// "LEADS JSON:" (space instead of underscore). Accept either.
const match = raw.match(/[*_`\s]*LEADS[_ ]JSON:[*_`\s]*(\[[\s\S]*\])[*_`\s]*$/i);

function tryParse(str) {
  try {
    const parsed = JSON.parse(str);
    return Array.isArray(parsed) ? parsed : null;
  } catch (e) {
    return null;
  }
}

if (match) {
  cleanText = raw.slice(0, match.index).trim();
  const jsonStr = match[1];
  let parsed = tryParse(jsonStr);

  // Repair attempt: LLM sometimes forgets a closing "}" before the final "]".
  if (!parsed) {
    const openBraces = (jsonStr.match(/\{/g) || []).length;
    const closeBraces = (jsonStr.match(/\}/g) || []).length;
    if (openBraces > closeBraces) {
      const missing = openBraces - closeBraces;
      const lastBracket = jsonStr.lastIndexOf(']');
      if (lastBracket !== -1) {
        const repaired = jsonStr.slice(0, lastBracket) + '}'.repeat(missing) + jsonStr.slice(lastBracket);
        parsed = tryParse(repaired);
      }
    }
  }

  if (parsed) {
    leads = parsed.filter(l => l && l.found === true && l.name);
  }
}

if (leads.length === 0) {
  return [{ json: { cleanText, isLead: false } }];
}
return leads.map(l => ({ json: {
  cleanText,
  isLead: true,
  leadName: l.name,
  leadCompany: l.company || null,
  leadContactInfo: l.contact_info || l['contact info'] || null,
  leadNotes: l.notes || null,
  leadPriority: ['A','B','C','D'].includes(l.priority) ? l.priority : null,
  leadFollowupDays: typeof l.followup_days === 'number' ? l.followup_days : null,
  leadLanguage: (typeof l.language === 'string' && /^[a-z]{2}$/.test(l.language.trim().toLowerCase()))
    ? l.language.trim().toLowerCase()
    : 'de'
} }));

const collected = $('Vision-Prompt bauen (Media-Group)').first().json;
const cleanText = $('Vision Leads JSON parsen (Media-Group)').first().json.cleanText;
const lines = $input.all().map(i => i.json.line).filter(Boolean);
const suffix = lines.length ? `\n\n${lines.join('\n')}` : '';
const rawText = `${cleanText}${suffix}`;

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/_/g, ' ')
    .replace(/\*/g, ' ')
    .replace(/`/g, "'");
}

function wrapMessageSuggestion(text) {
  // Wickelt JEDEN "Nachrichtenvorschlag:"-Abschnitt in <pre> (Telegram HTML) fuer Ein-Tap-
  // Copy-Paste. Bei Media-Group-Alben mit mehreren Kontakten kommt der Abschnitt pro Kontakt
  // vor, daher global (/g). Abschlussgrenze: "---"-Trennzeile ODER "Optionaler
  // LinkedIn-Kommentar:" ODER naechster "Kontakt:"-Block ODER Textende -- je nachdem was
  // zuerst kommt. Vorherige Version erwartete nur Whitespace vor "Optionaler
  // LinkedIn-Kommentar:", aber das Modell trennt Abschnitte konsequent mit eigenen
  // "---"-Trennzeilen dazwischen -- dadurch griff die alte Grenze nie und der komplette Rest
  // des Textes (inkl. naechster Abschnitte) landete im <pre>-Block bzw. verhinderte das
  // Wrapping in der Media-Group-Variante komplett (dort gab es die Funktion bisher gar nicht).
  return text.replace(
    /(\bNachrichtenvorschlag:[ \t]*\n?)([\s\S]*?)(?=\n\s*-{3,}\s*\n|\n\s*Optionaler LinkedIn-Kommentar:|\n\s*(?:#{1,3}\s*)?Kontakt:\s|$)/gi,
    (full, header, message) => {
      const trimmed = message.trim();
      if (!trimmed) return full;
      return `${header}\n<pre><code class="language-plain">${trimmed}</code></pre>`;
    }
  );
}

return [{
  json: {
    replyText: wrapMessageSuggestion(escapeHtml(rawText)),
    tenant_id: collected.tenant_id,
    telegram_chat_id: collected.telegram_chat_id
  }
}];

const fullText = $json.replyText || $('Vision-Antwort formatieren (Media-Group)').item.json.replyText;
const chatId = $json.telegram_chat_id || $('Vision-Antwort formatieren (Media-Group)').item.json.telegram_chat_id;

// Telegram hard-limits a single message to 4096 chars. Stay safely under that.
const MAX_LEN = 3800;

function splitText(text, maxLen) {
  if (!text || text.length <= maxLen) return [text || ''];
  const paragraphs = text.split(/\n\n+/);
  const chunks = [];
  let current = '';
  for (const p of paragraphs) {
    const candidate = current ? `${current}\n\n${p}` : p;
    if (candidate.length > maxLen) {
      if (current) chunks.push(current);
      if (p.length > maxLen) {
        // A single paragraph is itself too long -- hard-split it as a last resort.
        for (let i = 0; i < p.length; i += maxLen) {
          chunks.push(p.slice(i, i + maxLen));
        }
        current = '';
      } else {
        current = p;
      }
    } else {
