// Termin Erfolg Reply (NEU 23.09.2026)
// Baut die Erfolgsbestaetigung fuer create_event deterministisch aus calendar_text,
// statt der LLM-eigenen "reply"-Formulierung zu vertrauen.
// Bug (23.09.2026): LLM schrieb bei einem echten Samstags-Termin (calendar_text
// korrekt "2026-09-26 ..."), faelschlich "Termin am Freitag, 26.09.2026 ..." --
// Wochentag war reine LLM-Erfindung, nicht aus dem tatsaechlichen Datum abgeleitet.
// Gleiches Architekturprinzip wie beim 18.06.2026-Fix im alten Kalender-Workflow:
// Wochentage NIE vom LLM berechnen lassen, immer deterministisch aus dem ISO-Datum.
const calendarText = $('Intent Parser').first().json.calendar_text || $('Pending Event laden').first().json.calendar_text || '';

const weekdayNames = ['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'];
const dateMatch = calendarText.match(/(\d{4})-(\d{2})-(\d{2})/);

let reply;
if (dateMatch) {
  const year  = parseInt(dateMatch[1], 10);
  const month = parseInt(dateMatch[2], 10) - 1;
  const day   = parseInt(dateMatch[3], 10);
  const d = new Date(year, month, day);
  const weekday = weekdayNames[d.getDay()];
  const pad = (n) => String(n).padStart(2, '0');
  const dateLabel = `${pad(day)}.${pad(month + 1)}.${year}`;

  let rest = calendarText.replace(/\d{4}-\d{2}-\d{2}/, '').replace(/\s+/g, ' ').trim();
  rest = rest.replace(/\btermin\b/gi, '').replace(/\s+/g, ' ').trim();
  if (/^\d/.test(rest)) rest = 'um ' + rest;

  reply = `Termin am ${weekday}, ${dateLabel}${rest ? ' ' + rest : ''} wurde angelegt.`;
} else {
  reply = 'Termin wurde angelegt.';
}

return [{ json: { reply } }];

// Memory Speicher Erfolg Reply (NEU 24.09.2026, angepasst 24.09.2026 fuer Multi-Item-Save)
// Liest jetzt $json (per-Item aus Postgres RETURNING) statt $('Intent Parser').first() --
// laeuft pro Memory-Eintrag einzeln, damit mehrere Punkte aus einer Nachricht
// (z.B. lange Sprachnotiz) je eine eigene, wochentag-korrekte Bestaetigungszeile bekommen.
// Baut die Bestaetigung fuer save_memory deterministisch, statt der LLM-eigenen
// "reply"-Formulierung zu vertrauen -- gleiches Prinzip wie "Termin Erfolg Reply"
// beim create_event-Fix: Wochentag wird nie vom LLM erfunden, sondern immer aus
// due_date berechnet.
const type = $json.type || 'note';
const content = $json.content || '';
const dueDate = $json.due_date;

const typeLabels = { task: 'Aufgabe', deal: 'Deal', reminder: 'Erinnerung', note: 'Notiz', expense: 'Ausgabe' };
const typeLabel = typeLabels[type] || 'Notiz';

const weekdayNames = ['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'];

let dueDateLabel = '';
if (dueDate && dueDate !== 'null') {
  const m = String(dueDate).match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) {
    const year  = parseInt(m[1], 10);
    const month = parseInt(m[2], 10) - 1;
    const day   = parseInt(m[3], 10);
    const d = new Date(year, month, day);
    const weekday = weekdayNames[d.getDay()];
    const pad = (n) => String(n).padStart(2, '0');
    dueDateLabel = ` (faellig ${weekday}, ${pad(day)}.${pad(month + 1)}.${year})`;
  }
}

const amount = typeof $json.amount === 'number' ? $json.amount : null;
const amountLabel = amount !== null ? ` — ${amount.toFixed(2).replace('.', ',')} €` : '';
const reply = `Gemerkt (${typeLabel}): ${content}${amountLabel}${dueDateLabel}.`;

return [{ json: { reply } }];

// Jonas -- save_memory Multi-Item-Split (24.09.2026)
// Erlaubt mehrere Memory-Eintraege aus EINER Nachricht (z.B. lange Sprachnotiz
// nach einem Call mit mehreren Punkten). Bei einem "items"-Array im Intent-
// Parser-Ergebnis wird pro Eintrag ein eigenes n8n-Item erzeugt (-> eigener
// Insert + eigene Bestaetigungszeile pro Eintrag, gleiches Muster wie
// LEADS_JSON beim Media-Group-Feature). Ohne "items" (Normalfall: ein
// einzelner Punkt) exakt 1 Item mit den bisherigen Feldern --
// 100% rueckwaertskompatibel zum bisherigen Verhalten.
const intentData = $('Intent Parser').first().json;
const items = Array.isArray(intentData.items) && intentData.items.length > 0
  ? intentData.items
  : [{ type: intentData.type, content: intentData.content, due_date: intentData.due_date, amount: intentData.amount }];

return items
  .filter(it => it && it.content)
  .map(it => ({
    json: {
      type: it.type || 'note',
      content: it.content,
      due_date: (it.due_date && it.due_date !== 'null') ? it.due_date : null,
      amount: (typeof it.amount === 'number') ? it.amount : null
    }
  }));

// Jonas -- save_memory Multi-Item-Konsolidierung (24.09.2026)
// "Memory Speicher Erfolg Reply" und "Memory Save Fehler Reply" liefern jetzt
// PRO EINTRAG je ein eigenes Item mit derselben Form { reply }. Dieser Node
// laeuft nach dem Merge der beiden Zweige einmal fuer die gesamte Execution
// und fuegt alle Zeilen zu GENAU EINER finalen Nachricht zusammen -- "Reply
// extrahieren"/Telegram-Versand sind weiterhin auf exakt 1 finales Item
// pro Execution ausgelegt. Fuer den Normalfall (ein Eintrag) identisch zum
// bisherigen Verhalten (genau eine Zeile durchgereicht).
const all = $input.all();
const replies = all.map(item => (item.json || {}).reply).filter(Boolean);
const reply = replies.length ? replies.join('\n') : 'Alles klar.';
return [{ json: { reply } }];

