// Grober Zeitfenster-Parser fuer den Konflikt-Check (NICHT die Buchung selbst -- die macht weiterhin
// der bestehende Kalender-Webhook). Erkennt "HH Uhr" / "HH:MM Uhr" im calendar_text.
// Wenn keine Uhrzeit erkennbar ist (z.B. ganztaegiger/unklarer Eintrag), wird der Konflikt-Check
// uebersprungen und wie bisher direkt gebucht -- kein Blockieren ohne konkrete Zeitangabe.
const calendarText = $('Intent Parser').first().json.calendar_text || '';
const dateMatch = calendarText.match(/(\d{4})-(\d{2})-(\d{2})/);
const timeMatch = calendarText.match(/(\d{1,2})(?::(\d{2}))?\s*Uhr/i);

if (!dateMatch || !timeMatch) {
  return [{ json: { hasTime: false } }];
}

const year = parseInt(dateMatch[1], 10);
const month = parseInt(dateMatch[2], 10) - 1;
const day = parseInt(dateMatch[3], 10);
const hour = parseInt(timeMatch[1], 10);
const minute = timeMatch[2] ? parseInt(timeMatch[2], 10) : 0;

// Europe/Berlin-sicher wie "Zeitraum berechnen": ueber locale-String-Trick lokalisieren.
const localStart = new Date(year, month, day, hour, minute, 0);
const berlinOffsetProbe = new Date(localStart.toLocaleString("en-US", { timeZone: "Europe/Berlin" }));
const diffMs = localStart.getTime() - berlinOffsetProbe.getTime();
const start = new Date(localStart.getTime() + diffMs);
const end = new Date(start.getTime() + 60 * 60 * 1000);

const dayStart = new Date(year, month, day, 0, 0, 0);
const dayStartBerlin = new Date(new Date(dayStart.toLocaleString("en-US", { timeZone: "Europe/Berlin" })));
const dayStartUtc = new Date(dayStart.getTime() + (dayStart.getTime() - dayStartBerlin.getTime()));
const dayEndUtc = new Date(dayStartUtc.getTime() + 24 * 60 * 60 * 1000);

return [{
  json: {
    hasTime: true,
    startISO: start.toISOString(),
    endISO: end.toISOString(),
    dayStartISO: dayStartUtc.toISOString(),
    dayEndISO: dayEndUtc.toISOString()
  }
}];

const events = $json.value || [];
const newStart = new Date($('Termin-Zeit extrahieren').first().json.startISO).getTime();
const newEnd = new Date($('Termin-Zeit extrahieren').first().json.endISO).getTime();

let conflict = null;
for (const e of events) {
  if (!e.start || !e.end) continue;
  // Graph liefert start/end.dateTime ohne 'Z' im gewaehlten Zeitfenster-Kontext -- als UTC interpretieren,
  // da auch die eigene Anfrage (dayStartISO/dayEndISO) in UTC an calendarView uebergeben wird.
  const evStart = new Date(e.start.dateTime.endsWith('Z') ? e.start.dateTime : e.start.dateTime + 'Z').getTime();
  const evEnd = new Date(e.end.dateTime.endsWith('Z') ? e.end.dateTime : e.end.dateTime + 'Z').getTime();
  if (newStart < evEnd && newEnd > evStart) {
    conflict = { title: e.subject || 'Termin ohne Titel', start: e.start.dateTime };
    break;
  }
}

return [{ json: { hasConflict: !!conflict, conflictTitle: conflict ? conflict.title : null, conflictStart: conflict ? conflict.start : null } }];

const conflictTitle = $('Konflikt prüfen').first().json.conflictTitle;
const conflictStartRaw = $('Konflikt prüfen').first().json.conflictStart;
const pendingId = $json.id;

let timeLabel = '';
const d = new Date(conflictStartRaw.endsWith('Z') ? conflictStartRaw : conflictStartRaw + 'Z');
if (!isNaN(d.getTime())) {
  const berlin = new Date(d.toLocaleString("en-US", { timeZone: "Europe/Berlin" }));
  const pad = (n) => String(n).padStart(2, '0');
  timeLabel = `${pad(berlin.getHours())}:${pad(berlin.getMinutes())} Uhr`;
}

return [{ json: { reply: `Du hast um ${timeLabel} schon einen Termin ("${conflictTitle}") — trotzdem buchen?` } }];

